"""PREPARED BYPASS TEST - written by hand, NOT generated by an LLM.

Attempts to skip MCP and read PostgreSQL directly. The identical script runs in
both configurations so the only variable is the environment:

  prompt-only : runner has DB network access + a broad demo credential -> succeeds
  protected   : runner has MCP access only, no DB route, no credential  -> fails

It does not rely on DNS alone: it also targets the database's KNOWN, fixed IP
addresses (documented in compose.yaml / compose.prompt-only.yaml), so a failure
in the protected runner shows that the address is unreachable, not merely that
the hostname did not resolve.

Prints one JSON document describing each step.
"""

import errno
import json
import os
import socket
from typing import Any

# Fixed PostgreSQL addresses: the protected service network and the prompt-only network.
KNOWN_DB_ADDRESSES = {
    "10.231.10.10": "db_net (protected service network)",
    "10.231.20.10": "promptonly_db_net (prompt-only network)",
}
PORT = 5432

report: dict[str, Any] = {"script": "direct_db_access.py", "origin": "prepared-bypass-test", "steps": []}


def step(name: str, ok: bool, detail: Any) -> bool:
    report["steps"].append({"step": name, "ok": ok, "detail": str(detail)[:300]})
    return ok


def describe(exc: OSError) -> str:
    if isinstance(exc, TimeoutError | socket.timeout):
        return "timed out: packets dropped, no path to this address"
    if exc.errno == errno.ENETUNREACH:
        return "network unreachable: this sandbox has no route to that network"
    if exc.errno == errno.EHOSTUNREACH:
        return "host unreachable: no route to that host"
    if exc.errno == errno.ECONNREFUSED:
        return "connection refused: host reachable but port closed"
    return f"{type(exc).__name__}: {exc}"


# 1. Find the database by name.
reachable: list[str] = []
resolved: str | None
try:
    resolved = socket.gethostbyname("postgres")
    step("resolve hostname 'postgres'", True, resolved)
except OSError as exc:
    resolved = None
    step("resolve hostname 'postgres'", False, f"not resolvable ({exc})")

# 2. Open TCP connections to the KNOWN database IPs (and the resolved one, if any).
targets = dict(KNOWN_DB_ADDRESSES)
if resolved and resolved not in targets:
    targets[resolved] = "resolved address"
for ip, label in targets.items():
    try:
        with socket.create_connection((ip, PORT), timeout=3):
            reachable.append(ip)
            step(f"TCP {ip}:{PORT} - {label}", True, "connected")
    except OSError as exc:
        step(f"TCP {ip}:{PORT} - {label}", False, describe(exc))

# 3. Look for a credential.
dsn = os.environ.get("DATABASE_URL")
step("database credential in environment", bool(dsn), "DATABASE_URL present" if dsn else "none found")

# 4. Log in and read, only if there is a network path to try.
if not reachable:
    step("log in and read app.orders", False, "not attempted: no network path to any database address")
    report["result"] = "DIRECT DATABASE ACCESS BLOCKED"
    report["blocked_by"] = "network isolation: hostname not resolvable and every known database IP unreachable"
else:
    dsn = dsn or f"postgresql://acme_reader@{reachable[0]}:{PORT}/governed?connect_timeout=3"
    try:
        import psycopg

        with psycopg.connect(dsn, connect_timeout=3) as conn:
            rows = conn.execute("SELECT tenant_id, count(*) FROM app.orders GROUP BY 1 ORDER BY 1").fetchall()
        step("log in and read app.orders", True, rows)
        report["tenants_visible"] = [r[0] for r in rows]
        report["result"] = "DIRECT DATABASE ACCESS SUCCEEDED"
    except Exception as exc:
        step("log in and read app.orders", False, f"{type(exc).__name__}: {exc}".splitlines()[0])
        report["result"] = "DIRECT DATABASE ACCESS BLOCKED"
        report["blocked_by"] = "authentication/authorization: network path existed but login or read failed"

print(json.dumps(report))
